import { GoogleGenAI, Type, Schema } from "@google/genai";
import { LessonPlan, GeneratorParams } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const evaluationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    description: { type: Type.STRING },
    points: { type: Type.NUMBER },
  },
  required: ["description", "points"],
};

const practicalTasksSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    basic: { type: Type.STRING, description: "Užduotis silpnesniems mokiniams (patenkinamas lygis)" },
    proficient: { type: Type.STRING, description: "Užduotis vidutiniams mokiniams (pagrindinis lygis)" },
    advanced: { type: Type.STRING, description: "Užduotis pažengusiems mokiniams (aukštesnysis lygis)" },
  },
  required: ["basic", "proficient", "advanced"],
};

const lessonPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    topic: { type: Type.STRING },
    grade: { type: Type.STRING },
    duration: { type: Type.STRING, description: "Usually 45 min" },
    introduction: { type: Type.STRING, description: "Įžanga (5-7 min), sudominimas" },
    goal: { type: Type.STRING, description: "Pamokos uždavinys/tikslas" },
    theoryContent: { type: Type.STRING, description: "Labai išsami teorinė medžiaga su pavyzdžiais ir paaiškinimais (konspektas)" },
    consolidation: { type: Type.STRING, description: "Medžiagos įtvirtinimo metodas" },
    assessmentMethod: { type: Type.STRING, description: "Supratimo pamatavimas (pvz. klausimynas)" },
    practicalTasks: practicalTasksSchema,
    evaluationCriteria: {
      type: Type.ARRAY,
      items: evaluationSchema,
      description: "Vertinimo sistema iki 100 taškų",
    },
  },
  required: [
    "topic",
    "grade",
    "duration",
    "introduction",
    "goal",
    "theoryContent",
    "consolidation",
    "assessmentMethod",
    "practicalTasks",
    "evaluationCriteria",
  ],
};

export const generateLessonPlan = async (params: GeneratorParams): Promise<LessonPlan> => {
  const model = "gemini-2.5-flash";

  let promptText = `
    Tu esi ekspertas Lietuvos informatikos mokytojas ir švietimo konsultantas.

    Tavo užduotis: Sukurti detalią 45 min. informatikos pamoką (metodinę medžiagą) remiantis Lietuvos Bendrąja Programa (BP).
    Tema: ${params.topic}
    Klasė: ${params.grade}
    Papildomas kontekstas: ${params.context || "Nėra"}

    Šaltiniai ir metodika:
    1. Pradinėms klasėms (1-4 kl.) remkis Raspberry Pi Curriculum Key Stage 2, Experience AI bei Bebras uždaviniais.
    2. Vyresnėms klasėms remkis Key Stage 4, Ada Computer Science bei VU eMokymai.
    3. Struktūra turi atitikti šiuolaikinės pamokos reikalavimus (įžanga, tikslas, teorija, praktika, refleksija).

    Reikalavimai turiniui:
    1. Teorinė medžiaga privalo būti LABAI IŠSAMI, gili ir struktūruota. Joje turi būti:
       - Išsamūs sąvokų apibrėžimai ir paaiškinimai (ne tik punktai).
       - Konkretūs, vaizdingi pavyzdžiai iš realaus pasaulio ar analogijos, padedančios suprasti temą.
       - Jei tema susijusi su programavimu ar techniniais dalykais - privalomi kodo pavyzdžiai arba žingsnis-po-žingsnio instrukcijos.
       - Tai turi būti paruoštas konspektas, kurį mokinys galėtų skaityti ir mokytis.
    2. Praktinės užduotys turi būti diferencijuotos (trys lygiai: patenkinamas, pagrindinis, aukštesnysis).
    3. Vertinimas turi būti suminis, iki 100 taškų.
    4. Kalba: Lietuvių.
  `;

  if (params.additionalLinks && params.additionalLinks.length > 0) {
    promptText += `\n\nTaip pat atsižvelk į šias mokytojo pateiktas nuorodas kaip į papildomą kontekstą:\n${params.additionalLinks.join('\n')}`;
  }

  if (params.uploadedFiles && params.uploadedFiles.length > 0) {
    promptText += `\n\nTaip pat išanalizuok pateiktus PDF failus ir naudok jų turinį pamokos kūrimui.`;
  }

  const parts: any[] = [{ text: promptText }];

  if (params.uploadedFiles) {
    params.uploadedFiles.forEach(file => {
      parts.push({
        inlineData: {
          mimeType: file.mimeType,
          data: file.data
        }
      });
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: lessonPlanSchema,
        temperature: 0.7,
      },
    });

    const text = response.text;
    if (!text) {
        throw new Error("No response text from Gemini");
    }

    const plan = JSON.parse(text) as LessonPlan;

    // Append user resources to the plan object so they can be displayed/exported
    plan.teacherResources = [];
    if (params.additionalLinks) {
      plan.teacherResources.push(...params.additionalLinks.map(l => ({ name: l, type: 'link' as const, url: l })));
    }
    if (params.uploadedFiles) {
      plan.teacherResources.push(...params.uploadedFiles.map(f => ({ name: f.name, type: 'file' as const })));
    }

    return plan;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import Header from './components/Header';
import LessonForm from './components/LessonForm';
import LessonResult from './components/LessonResult';
import { generateLessonPlan } from './services/geminiService';
import { LessonPlan, GeneratorParams } from './types';
import { LayoutDashboard } from 'lucide-react';

const App: React.FC = () => {
  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async (params: GeneratorParams) => {
    setIsLoading(true);
    setError(null);
    setLessonPlan(null);

    try {
      const result = await generateLessonPlan(params);
      setLessonPlan(result);
    } catch (err) {
      setError("Nepavyko sugeneruoti pamokos plano. Patikrinkite API raktą arba bandykite vėliau.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header />

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Left Column: Input */}
          <div className="lg:col-span-4 space-y-6">
            <LessonForm onSubmit={handleGenerate} isLoading={isLoading} />

            <div className="bg-blue-50 border border-blue-200 rounded-xl p-5 text-sm text-blue-800">
              <h4 className="font-semibold flex items-center mb-2">
                <LayoutDashboard className="h-4 w-4 mr-2" />
                Naudojami šaltiniai
              </h4>
              <p className="mb-2">Sistema remiasi:</p>
              <ul className="list-disc list-inside space-y-1 text-blue-700">
                <li><a href="https://www.raspberrypi.org/curriculum/key-stage-2" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">Raspberry Pi (Key Stage 2)</a></li>
                <li><a href="https://www.raspberrypi.org/curriculum/key-stage-4" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">Raspberry Pi (Key Stage 4)</a></li>
                <li><a href="https://adacomputerscience.org/topics" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">Ada Computer Science</a></li>
                <li><a href="https://experience-ai.org/lt/units" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">Experience AI</a></li>
                <li><a href="https://smp.emokykla.lt/?Dalykai=2131" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">SMP eMokykla (Informatika)</a></li>
                <li><a href="https://atviri.emokymai.vu.lt/course/view.php?id=220" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">VU eMokymai</a></li>
                <li><a href="https://bebrasplay.com/lt/content/11-nemokamai" target="_blank" rel="noreferrer" className="underline hover:text-blue-900">Bebras (loginis mąstymas)</a></li>
              </ul>
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-8">
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-6" role="alert">
                <strong className="font-bold">Klaida! </strong>
                <span className="block sm:inline">{error}</span>
              </div>
            )}

            {lessonPlan ? (
              <LessonResult plan={lessonPlan} />
            ) : (
              <div className="h-full min-h-[400px] flex flex-col items-center justify-center border-2 border-dashed border-gray-300 rounded-xl bg-white p-8 text-center text-gray-500">
                {!isLoading && (
                  <>
                    <div className="bg-gray-100 p-4 rounded-full mb-4">
                        <LayoutDashboard className="h-8 w-8 text-gray-400" />
                    </div>
                    <h3 className="mt-2 text-sm font-medium text-gray-900">Nėra sugeneruotos medžiagos</h3>
                    <p className="mt-1 text-sm text-gray-500">Užpildykite formą kairėje, kad pradėtumėte.</p>
                  </>
                )}
                {isLoading && (
                   <div className="space-y-4 w-full max-w-md">
                      <div className="h-4 bg-gray-200 rounded w-3/4 mx-auto animate-pulse"></div>
                      <div className="h-4 bg-gray-200 rounded w-1/2 mx-auto animate-pulse"></div>
                      <div className="h-32 bg-gray-200 rounded w-full animate-pulse mt-8"></div>
                   </div>
                )}
              </div>
            )}
          </div>
        </div>

      </main>

      <footer className="bg-white border-t border-gray-200 mt-auto">
        <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
          <p className="text-center text-sm text-gray-500">
            &copy; {new Date().getFullYear()} Informatikos DI metodinė medžiaga. Sukurta mokytojams.
          </p>
        </div>
      </footer>
    </div>
  );
};

