import React from 'react';
import { LessonPlan } from '../types';
import { Download, FileText, CheckCircle, Clock, Target, BookOpen, Brain, Activity, Paperclip, ExternalLink, HelpCircle, Printer } from 'lucide-react';

interface LessonResultProps {
  plan: LessonPlan;
}

const LessonResult: React.FC<LessonResultProps> = ({ plan }) => {

  const handleExportTxt = () => {
    let content = `
PAMOKOS PLANAS: ${plan.topic}
Klasė: ${plan.grade}
Trukmė: ${plan.duration}

1. ĮŽANGA
${plan.introduction}

2. PAMOKOS TIKSLAS
${plan.goal}

3. TEORINĖ MEDŽIAGA
${plan.theoryContent}

4. ĮTVIRTINIMO KLAUSIMAI (KAIP SUPRATO TEORIJĄ?)
${plan.checkUnderstandingQuestions.map((q, i) => `${i+1}. ${q}`).join('\n')}

5. PRAKTINĖS UŽDUOTYS
1. (Silpnesniems): ${plan.practicalTasks.basic}
2. (Vidutiniams): ${plan.practicalTasks.proficient}
3. (Pažengusiems): ${plan.practicalTasks.advanced}

6. VERTINIMAS (Iš viso 100 tšk.)
${plan.evaluationCriteria.map(c => `- ${c.description}: ${c.points} tšk.`).join('\n')}
