    proficient: { type: Type.STRING, description: "2-oji praktinė užduotis: Standartinė, skirta daugumai (pagrindinis lygis)" },
    advanced: { type: Type.STRING, description: "3-ioji praktinė užduotis: Sunki/kūrybinė, skirta pažengusiems (aukštesnysis lygis)" },
  },
  required: ["basic", "proficient", "advanced"],
};

const lessonPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    topic: { type: Type.STRING },
    grade: { type: Type.STRING },
    duration: { type: Type.STRING, description: "Usually 45 min" },
    introduction: { type: Type.STRING, description: "Įžanga (5-7 min), sudominimas" },
    goal: { type: Type.STRING, description: "Pamokos uždavinys/tikslas" },
    theoryContent: { type: Type.STRING, description: "Labai išsami teorinė medžiaga su pavyzdžiais ir paaiškinimais (konspektas)" },
    checkUnderstandingQuestions: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "3 konkretūs klausimai arba trumpos užduotys patikrinti, kaip mokiniai suprato teoriją" 
    },
    practicalTasks: practicalTasksSchema,
    evaluationCriteria: {
      type: Type.ARRAY,
      items: evaluationSchema,
      description: "Vertinimo sistema iki 100 taškų, tik už praktines užduotis",
    },
  },
  required: [
    "topic",
