  let promptText = `
    Tu esi ekspertas Lietuvos informatikos mokytojas ir švietimo konsultantas.

    Tavo užduotis: Sukurti detalią 45 min. informatikos pamoką (metodinę medžiagą) remiantis Lietuvos Bendrąja Programa (BP).
    Tema: ${params.topic}
    Klasė: ${params.grade}
    Papildomas kontekstas: ${params.context || "Nėra"}

    Šaltiniai ir metodika:
    1. Pradinėms klasėms (1-4 kl.) remkis Raspberry Pi Curriculum Key Stage 2, Experience AI bei Bebras uždaviniais.
    2. Vyresnėms klasėms remkis Key Stage 4, Ada Computer Science, SMP eMokykla (Informatika) bei VU eMokymai.
    3. Struktūra turi atitikti šiuolaikinės pamokos reikalavimus (įžanga, tikslas, teorija, įtvirtinimas, praktika, refleksija).

    Reikalavimai turiniui:
    1. Teorinė medžiaga privalo būti LABAI IŠSAMI, gili ir struktūruota. Joje turi būti:
       - Išsamūs sąvokų apibrėžimai ir paaiškinimai.
       - Konkretūs pavyzdžiai iš realaus pasaulio.
       - Kodo pavyzdžiai (jei taikoma).
    2. Įtvirtinimas: Pateik lygiai 3 klausimus/trumpas užduotis, kurios patikrina, ar mokinys suprato teoriją.
    3. Praktinės užduotys: Pateik 3 diferencijuotas praktines užduotis:
       - 1 užduotis (Basic): Lengva.
       - 2 užduotis (Proficient): Standartinė.
       - 3 užduotis (Advanced): Sunki/Kūrybinė.
    4. Vertinimas (viso 100 taškų):
       - Vertinimo kriterijai turi būti skirti TIK praktinėms užduotims vertinti.
       - GRIEZTAI NESKIRK taškų už teorijos skaitymą, aktyvumą pamokoje ar atsakymus į įtvirtinimo klausimus.
       - Visi 100 taškų turi susidėti iš konkrečių praktinių veiksmų (pvz., "Teisingai panaudotas ciklas - 20 tšk.", "Programa veikia be klaidų - 30 tšk.").
    5. Kalba: Lietuvių.
  `;

  if (params.additionalLinks && params.additionalLinks.length > 0) {
    promptText += `\n\nTaip pat atsižvelk į šias mokytojo pateiktas nuorodas kaip į papildomą kontekstą:\n${params.additionalLinks.join('\n')}`;
  }

  if (params.uploadedFiles && params.uploadedFiles.length > 0) {
    promptText += `\n\nTaip pat išanalizuok pateiktus PDF failus ir naudok jų turinį pamokos kūrimui.`;
  }

  const parts: any[] = [{ text: promptText }];

  if (params.uploadedFiles) {
    params.uploadedFiles.forEach(file => {
      parts.push({
        inlineData: {
          mimeType: file.mimeType,
          data: file.data
        }
      });
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: lessonPlanSchema,
        temperature: 0.7,
      },
    });

    const text = response.text;
    if (!text) {
        throw new Error("No response text from Gemini");
    }

    const plan = JSON.parse(text) as LessonPlan;

    // Append user resources to the plan object so they can be displayed/exported
    plan.teacherResources = [];
    if (params.additionalLinks) {
      plan.teacherResources.push(...params.additionalLinks.map(l => ({ name: l, type: 'link' as const, url: l })));
    }
    if (params.uploadedFiles) {
      plan.teacherResources.push(...params.uploadedFiles.map(f => ({ name: f.name, type: 'file' as const })));
    }

    return plan;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';
import { LessonPlan } from '../types';
import { Download, FileText, CheckCircle, Clock, Target, BookOpen, Brain, Activity, Paperclip, ExternalLink, HelpCircle, Printer, Save } from 'lucide-react';

interface LessonResultProps {
  plan: LessonPlan;
  onSave?: () => void;
  isSaved?: boolean;
}

const LessonResult: React.FC<LessonResultProps> = ({ plan, onSave, isSaved }) => {

  const handleExportTxt = () => {
    let content = `
PAMOKOS PLANAS: ${plan.topic}
Klasė: ${plan.grade}
Trukmė: ${plan.duration}

1. ĮŽANGA
${plan.introduction}

2. PAMOKOS TIKSLAS
${plan.goal}

3. TEORINĖ MEDŽIAGA
${plan.theoryContent}

4. ĮTVIRTINIMO KLAUSIMAI (KAIP SUPRATO TEORIJĄ?)
${plan.checkUnderstandingQuestions.map((q, i) => `${i+1}. ${q}`).join('\n')}

