        setSavedPlans(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved plans", e);
      }
    }
  }, []);

  const handleGenerate = async (params: GeneratorParams) => {
    setIsLoading(true);
    setError(null);
    setLessonPlan(null);
    setCurrentPlanId(null);

