import { SavedLessonPlan } from '../types';

const DB_NAME = 'InformatikosMetodineDB';
const STORE_NAME = 'plans';
const DB_VERSION = 1;

let dbPromise: Promise<IDBDatabase> | null = null;

const getDB = (): Promise<IDBDatabase> => {
  if (!dbPromise) {
    dbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };

      request.onsuccess = (event) => {
        resolve((event.target as IDBOpenDBRequest).result);
      };

      request.onerror = (event) => {
        reject((event.target as IDBOpenDBRequest).error);
      };
    });
  }
  return dbPromise;
};

export const storageService = {
  async getAllPlans(): Promise<SavedLessonPlan[]> {
    const db = await getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => {
        // Sort by createdAt descending (newest first)
        const plans = request.result as SavedLessonPlan[];
        resolve(plans.sort((a, b) => b.createdAt - a.createdAt));
      };
      request.onerror = () => reject(request.error);
    });
  },

  async savePlan(plan: SavedLessonPlan): Promise<void> {
    const db = await getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(plan);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  async deletePlan(id: string): Promise<void> {
    const db = await getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  async importPlans(plans: SavedLessonPlan[]): Promise<void> {
    const db = await getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);

      plans.forEach(plan => {
        // Validation: ensure it has an ID and required fields
        if (plan.id && plan.topic && plan.grade) {
            store.put(plan);
        }
      });
    });
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import LessonForm from './components/LessonForm';
import LessonResult from './components/LessonResult';
import { generateLessonPlan } from './services/geminiService';
import { storageService } from './services/storageService';
import { LessonPlan, GeneratorParams, SavedLessonPlan } from './types';
import { LayoutDashboard, Save, Trash2, ChevronRight, Download, Upload, Database } from 'lucide-react';

const App: React.FC = () => {
  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [savedPlans, setSavedPlans] = useState<SavedLessonPlan[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentPlanId, setCurrentPlanId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved plans from IndexedDB on mount
  useEffect(() => {
    loadSavedPlans();
  }, []);

  const loadSavedPlans = async () => {
    try {
      const plans = await storageService.getAllPlans();
      setSavedPlans(plans);
    } catch (err) {
      console.error("Failed to load plans from DB", err);
    }
  };

  const handleGenerate = async (params: GeneratorParams) => {
    setIsLoading(true);
    setError(null);
    setLessonPlan(null);
    setCurrentPlanId(null);

    try {
      const result = await generateLessonPlan(params);
      setLessonPlan(result);
    } catch (err) {
      setError("Nepavyko sugeneruoti pamokos plano. Patikrinkite API raktą arba bandykite vėliau.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSavePlan = async () => {
    if (!lessonPlan) return;

    const newPlan: SavedLessonPlan = {
      ...lessonPlan,
      id: Date.now().toString(),
      createdAt: Date.now(),
    };

    try {
      await storageService.savePlan(newPlan);
      await loadSavedPlans(); // Reload list
      setCurrentPlanId(newPlan.id);
    } catch (err) {
      console.error("Failed to save plan", err);
      setError("Nepavyko išsaugoti plano į duomenų bazę.");
    }
  };

  const handleDeletePlan = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!window.confirm("Ar tikrai norite ištrinti šį planą?")) return;

    try {
      await storageService.deletePlan(id);
      await loadSavedPlans(); // Reload list

      if (currentPlanId === id) {
          setLessonPlan(null);
          setCurrentPlanId(null);
      }
    } catch (err) {
      console.error("Failed to delete plan", err);
    }
  };

  const handleSelectPlan = (plan: SavedLessonPlan) => {
    setLessonPlan(plan);
    setCurrentPlanId(plan.id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // --- Import / Export Logic ---

  const handleExportData = () => {
    if (savedPlans.length === 0) {
      alert("Nėra išsaugotų planų eksportavimui.");
      return;
    }
    const dataStr = JSON.stringify(savedPlans, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_plans_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImportClick = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const plans = JSON.parse(json) as SavedLessonPlan[];

        if (!Array.isArray(plans)) throw new Error("Netinkamas failo formatas");

        await storageService.importPlans(plans);
        await loadSavedPlans();
        alert(`Sėkmingai importuota ${plans.length} planų.`);
      } catch (err) {
        console.error("Import error", err);
        alert("Nepavyko importuoti failo. Įsitikinkite, kad tai teisingas JSON atsarginės kopijos failas.");
      }
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <div className="print:hidden">
        <Header />
      </div>

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 print:p-0 print:w-full print:max-w-none">

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 print:block">
          {/* Left Column: Input & Saved Plans */}
          <div className="lg:col-span-4 space-y-6 print:hidden">
            <LessonForm onSubmit={handleGenerate} isLoading={isLoading} />

            {/* Saved Plans List */}
            {savedPlans.length > 0 && (
                <div className="bg-white border border-gray-200 rounded-xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
                        <h4 className="font-semibold text-gray-900 flex items-center">
                            <Save className="h-4 w-4 mr-2 text-primary" />
