                                <button 
                                    onClick={(e) => handleDeletePlan(plan.id, e)}
                                    className="text-gray-400 hover:text-red-500 p-1 rounded-md hover:bg-red-50 opacity-0 group-hover:opacity-100 transition-all"
                                    title="Ištrinti"
                                >
                                    <Trash2 className="h-4 w-4" />
                                </button>
                            </li>
                        ))}
                    </ul>
                </div>
            )}

