                    {/* Level 3 */}
                    <div className="flex flex-col md:flex-row gap-4 bg-orange-50 p-4 rounded-lg border border-orange-100 print:bg-white print:border-gray-200">
                        <div className="md:w-48 flex-shrink-0">
