                        availablePdfHeight = contentHeight;
                        availablePx = pageHeightPx;
                    }

                    let sliceHeightPx = Math.min(remainingHeightPx, availablePx);

                    // SMART SPLIT: Check for whitespace to avoid cutting text
                    // Only do this if we are not at the very end (remainingHeightPx > sliceHeightPx)
                    // and we have enough room to search up
                    if (remainingHeightPx > sliceHeightPx) {
                        const searchLimit = 100; // Search up to 100px up
                        const cutY = srcY + sliceHeightPx;
                        let foundWhite = false;

                        // Check lines scanning upwards from cutY
                        for (let y = 0; y < searchLimit; y++) {
                             const checkY = cutY - y;
                             if (checkY <= srcY) break; // Don't go back past start

                             // Get pixel data for this row (checking center and a few spots for performance)
                             // Or check full row
                             const imageData = ctx.getImageData(0, checkY, canvas.width, 1);
                             const data = imageData.data;
                             let isWhite = true;
                             for (let i = 0; i < data.length; i += 4) {
                                // Simple white/transparent check (R,G,B > 250)
                                if (data[i] < 250 || data[i+1] < 250 || data[i+2] < 250) {
                                    isWhite = false;
                                    break;
                                }
                             }

                             if (isWhite) {
                                 sliceHeightPx -= y;
                                 foundWhite = true;
                                 break;
                             }
                        }
                        // If no white space found, we default to the hard cut (sliceHeightPx)
                    }

                    const tempCanvas = document.createElement('canvas');
                    tempCanvas.width = canvas.width;
                    tempCanvas.height = sliceHeightPx;

                    const tempCtx = tempCanvas.getContext('2d');
                    if (tempCtx) {
                        tempCtx.fillStyle = '#ffffff';
                        tempCtx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
                        tempCtx.drawImage(
                            canvas, 
                            0, srcY, canvas.width, sliceHeightPx, 
                            0, 0, tempCanvas.width, sliceHeightPx
                        );

                        const sliceImgData = tempCanvas.toDataURL('image/png');
                        const sliceHeightPdf = (sliceHeightPx * imgWidth) / canvas.width;

                        pdf.addImage(sliceImgData, 'PNG', margin, currentY, imgWidth, sliceHeightPdf);

                        currentY += sliceHeightPdf;
                        srcY += sliceHeightPx;
                        remainingHeightPx -= sliceHeightPx;
                    } else {
                        break;
                    }
                }
                currentY += 5;
            }
        } else {
            const imgData = canvas.toDataURL('image/png');
            pdf.addImage(imgData, 'PNG', margin, currentY, imgWidth, imgHeight);
            currentY += imgHeight + 5;
        }
      }

      pdf.save(`Pamoka_${plan.topic.replace(/\s+/g, '_')}.pdf`);

    } catch (error) {
      console.error("PDF generation failed:", error);
      alert("Nepavyko sugeneruoti PDF. Bandykite spausdinti (Ctrl+P).");
    } finally {
      setIsDownloading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const renderTheoryContent = () => {
    try {
      // Use marked to parse markdown. 
      // Note: marked is loaded via importmap/global script, typically accessible as window.marked or import
      const html = marked.parse(plan.theoryContent) as string;
      return { __html: html };
    } catch (e) {
