                </h3>
                <p className="text-gray-700 leading-relaxed print:text-black">{plan.goal}</p>
            </div>
            </div>

            {/* Theory */}
            <div>
            <h3 className="text-xl font-bold text-gray-900 flex items-center mb-4 border-b pb-2 print:border-none">
